from pathlib import Path

p=Path('backend/main.py')
s=p.read_text()
s=s.replace('import logging\n', 'import logging\nimport httpx\n')
s=s.replace('from backend.services.irsa import IRSAUnavailableError, ObservationNotFoundError', 'from backend.services.irsa import IRSAUnavailableError, ObservationNotFoundError\nfrom backend.services.catalog import CatalogError, IRSAFileCatalog')
s=s.replace('spherex_service = SPHERExService()\n', 'spherex_service = SPHERExService()\nfile_catalog = IRSAFileCatalog()\n')
route='''\n@app.get("/api/catalog")\nasync def get_archive_catalog(\n    path: str = "",\n    q: str = "",\n    detector: str = "",\n    planning_period: str = "",\n    page: int = Query(1, ge=1),\n    page_size: int = Query(50, ge=1, le=100),\n    sort: str = "name",\n):\n    try:\n        return await file_catalog.search(path=path, query=q, detector=detector,\n                                         planning_period=planning_period, page=page,\n                                         page_size=page_size, sort=sort)\n    except ValueError as exc:\n        raise HTTPException(status_code=422, detail=str(exc)) from exc\n    except CatalogError as exc:\n        logger.error("IRSA IBE catalog request failed: %s", exc)\n        raise HTTPException(status_code=502, detail=str(exc)) from exc\n\n\n@app.get("/api/fits")\nasync def get_irsa_fits(path: str, request: Request):\n    try:\n        upstream, chunks = await file_catalog.stream_fits(path, request.headers.get("range"))\n    except ValueError as exc:\n        raise HTTPException(status_code=422, detail=str(exc)) from exc\n    except CatalogError as exc:\n        logger.error("IRSA FITS stream failed: %s", exc)\n        raise HTTPException(status_code=502, detail=str(exc)) from exc\n    except httpx.HTTPError as exc:\n        logger.exception("IRSA FITS transport error")\n        raise HTTPException(status_code=502, detail="Could not retrieve FITS product from IRSA") from exc\n    headers = {key: value for key, value in upstream.headers.items()\n               if key.lower() in {"content-length", "content-range", "accept-ranges", "last-modified", "etag"}}\n    headers["Content-Disposition"] = "inline"\n    return StreamingResponse(chunks, status_code=upstream.status_code,\n                             media_type=upstream.headers.get("content-type", "application/fits"),\n                             headers=headers)\n\n'''
s=s.replace('# The same-origin frontend avoids hard-coded localhost URLs and production CORS requirements.\n', route+'# The same-origin frontend avoids hard-coded localhost URLs and production CORS requirements.\n')
s=s.replace('from fastapi.responses import JSONResponse', 'from fastapi.responses import JSONResponse, StreamingResponse')
p.write_text(s)
